"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["3216"],{5623(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.opcao_declarada_fato.rotulo_invalido","status":422,"titulo":"O r\xf3tulo da op\xe7\xe3o \xe9 obrigat\xf3rio e respeita o tamanho m\xe1ximo"},"descricao":{"codigo":"uniplus.selecao.opcao_declarada_fato.rotulo_invalido","requisitos":[],"oQueAconteceu":["O processo declara as op\xe7\xf5es de um fato cuja fonte dos valores \xe9 o pr\xf3prio\\nprocesso, como as edi\xe7\xf5es do ENEM aceitas. Cada op\xe7\xe3o tem um r\xf3tulo, que \xe9 o\\ntexto com que ela aparece para quem escolhe. O r\xf3tulo de pelo menos uma das\\nop\xe7\xf5es enviadas n\xe3o pode ser usado: veio em branco, s\xf3 com espa\xe7os, ou passou de\\n300 caracteres. Os espa\xe7os do in\xedcio e do fim n\xe3o contam.","A confer\xeancia percorre a lista inteira antes de recusar. A resposta traz um\\nerro por op\xe7\xe3o com problema, cada um indicando a posi\xe7\xe3o da op\xe7\xe3o na lista\\n(`opcoes[n].rotulo`), e nada foi gravado, nem das op\xe7\xf5es que estavam corretas."],"comoResolver":["Informe, em cada op\xe7\xe3o apontada, um r\xf3tulo preenchido com no m\xe1ximo 300\\ncaracteres, e envie a lista completa de novo. O pedido substitui todas as op\xe7\xf5es\\ndo fato, ent\xe3o a lista enviada precisa trazer tamb\xe9m as op\xe7\xf5es que j\xe1 valiam."],"ondeAparece":["Declara\xe7\xe3o das op\xe7\xf5es de um fato do processo seletivo (`PUT /api/selecao/processos-seletivos/{id}/fatos/{fatoCodigo}/opcoes`)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Opcao declarada fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"e5dad467d85ce0f062b88f68241ad834bc540cf0"}}')}}]);